"""Reorganize String — always place the two most frequent remaining letters.

Greedily emitting the current top-2 guarantees no repeat lands next to itself;
if the most frequent letter exceeds (n + 1) // 2 the task is impossible.

Time: O(n log a)   Space: O(a)
"""
import heapq
from collections import Counter


class Solution:
    def reorganizeString(self, s: str) -> str:
        counts = Counter(s)
        if max(counts.values()) > (len(s) + 1) // 2:
            return ""
        heap = [(-n, ch) for ch, n in counts.items()]
        heapq.heapify(heap)
        out = []
        while len(heap) > 1:
            n1, c1 = heapq.heappop(heap)
            n2, c2 = heapq.heappop(heap)
            out.append(c1)
            out.append(c2)
            if n1 + 1:
                heapq.heappush(heap, (n1 + 1, c1))
            if n2 + 1:
                heapq.heappush(heap, (n2 + 1, c2))
        if heap:
            out.append(heap[0][1])
        return "".join(out)
